const legacy = ['vol-x91c2','snap-x4d17','ip-x7a02','dns-x55e0'];
const intended = new Set([...selectForBranch(before, 'feat-ledger').map(r => r.id), ...legacy]);
const after = await new CloudClient(loadConfig()).listResources();
writeFileSync('/tmp/envctl-after.json', JSON.stringify(after, null, 2));
assert.deepEqual(after, before.filter(r => !intended.has(r.id)), 'Unrelated resources must be unchanged');
assert.deepEqual(buildPlan(after, 'feat-ledger'), {branch:'feat-ledger', steps:[], blocked:[]});
assert.ok(after.every(r => !intended.has(r.id)));
console.log(`Verified: ${before.length - after.length} intended resources removed; all ${after.length} unrelated resources unchanged, including feat-ledger-v2.`);
